solutions.java:
import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine().trim());
        HashMap<String, Integer> cnt = new HashMap<>();
        int best = 0;
        for (int i = 0; i < n; i++) {
            String w = br.readLine().trim();
            int[] c = new int[26];
            for (int j = 0; j < w.length(); j++) c[w.charAt(j) - 'a']++;
            String key = Arrays.toString(c);
            int v = cnt.merge(key, 1, Integer::sum);
            best = Math.max(best, v);
        }
        System.out.println(cnt.size() + " " + best);
    }
}

solutions.cpp:
#include <bits/stdc++.h>
using namespace std;
int main() {
    int n;
    cin >> n;
    map<array<int, 26>, int> cnt;
    int best = 0;
    for (int i = 0; i < n; i++) {
        string w;
        cin >> w;
        array<int, 26> c;
        c.fill(0);
        for (char ch : w) c[ch - 'a']++;
        best = max(best, ++cnt[c]);
    }
    cout << cnt.size() << " " << best << "\n";
    return 0;
}
